 12	package com.sun.fortress.compiler.desugarer;
 13	
 14	import com.sun.fortress.compiler.Types;
 15	import com.sun.fortress.compiler.WellKnownNames;
 16	import com.sun.fortress.nodes.*;
 17	import com.sun.fortress.nodes_util.*;
 18	import com.sun.fortress.useful.*;
 19	import com.sun.fortress.exceptions.CompilerError;
 20	import edu.rice.cs.plt.collect.IndexedRelation;
 21	import edu.rice.cs.plt.collect.Relation;
 22	import edu.rice.cs.plt.iter.IterUtil;
 23	import edu.rice.cs.plt.tuple.Option;
 24	import edu.rice.cs.plt.tuple.Pair;
 25	import java.util.Arrays;
 26	import java.util.ArrayList;
 27	import java.util.Collections;
 28	import java.util.List;
 29	import java.util.LinkedList;
 30	import java.util.Map;
 31	import java.math.BigInteger;
 32	import static com.sun.fortress.exceptions.InterpreterBug.bug;
 33	
 34	public class IntegerLiteralFoldingVisitor extends NodeUpdateVisitor {
 35		
 36		public IntegerLiteralFoldingVisitor() { }
 37		
 38		private BigInteger factorial_aux(BigInteger n, BigInteger acc) {
 39			if (n.compareTo(BigInteger.ZERO) == -1)
 40				throw new CompilerError("Integer Literal folding: Need to do something for factorial of negative values");
 41			if (n.equals(BigInteger.ZERO))
 42			   	return acc;
 43			else
 44				return factorial_aux(n.subtract(BigInteger.ONE),n.multiply(acc)); 
 45		}
 46		
 47		private BigInteger factorial(BigInteger n) {
 48			return factorial_aux(n,BigInteger.ONE);
 49		}
 50		
 51		private BigInteger choose(BigInteger n, BigInteger k) {
 52			BigInteger n_fact = factorial(n);
 53			BigInteger k_fact = factorial(k);
 54			BigInteger nminusk_fact = factorial(n.subtract(k));
 55			return n_fact.divide(k_fact.multiply(nminusk_fact));
 56		}
 57		
 58		private Node foldBinaryOperator(FunctionalRef op_result, ExprInfo info_result, Expr arg0, Expr arg1) {
 59			
 60			BigInteger v0 = ((IntLiteralExpr)arg0).getIntVal();
 61			BigInteger v1 = ((IntLiteralExpr)arg1).getIntVal();
 62			String op = op_result.toString();
 63			if (op.equals("+") || op.equals("\u229E") || op.equals("\u2214"))  // + BOXPLUS DOTPLUS 
 64				return ExprFactory.makeIntLiteralExpr(info_result,v0.add(v1));
 65			if (op.equals("-") || op.equals("\u229F") || op.equals("\u2238")) // - BOXMINUS DOTMINUS
 66				return ExprFactory.makeIntLiteralExpr(info_result,v0.subtract(v1));
 67			if (op.equals("BY") || op.equals("BOXCROSS") || op.equals("DOTCROSS") || op.equals("DOT") || op.equals("BOXDOT") || op.equals("juxtaposition"))
 68				return ExprFactory.makeIntLiteralExpr(info_result,v0.multiply(v1));
 69			if (op.equals("DIV") && v0.equals(BigInteger.ZERO) && v1.equals(BigInteger.ZERO)) 
 70				return ExprFactory.makeVarRef(info_result.getSpan(),WellKnownNames.compilerBuiltin(),WellKnownNames.UndefinedNumber());
 71			if (op.equals("DIV") && v0.compareTo(BigInteger.ZERO) == -1 && v1.equals(BigInteger.ZERO)) 
 72				return ExprFactory.makeVarRef(info_result.getSpan(),WellKnownNames.compilerBuiltin(),WellKnownNames.NegativeInfinity());
 73			if (op.equals("DIV") && v1.equals(BigInteger.ZERO)) 
 74				return ExprFactory.makeVarRef(info_result.getSpan(),WellKnownNames.compilerBuiltin(),WellKnownNames.Infinity());
 75			if (op.equals("DIV")) 
 76				return ExprFactory.makeIntLiteralExpr(info_result,v0.divide(v1));
 77			if (op.equals("AND"))
 78				return ExprFactory.makeIntLiteralExpr(info_result,v0.and(v1));
 79			if (op.equals("OR"))
 80				return ExprFactory.makeIntLiteralExpr(info_result,v0.or(v1));
 81			if (op.equals("XOR"))
 82				return ExprFactory.makeIntLiteralExpr(info_result,v0.xor(v1));
 83			if (op.equals("MIN"))
 84				return ExprFactory.makeIntLiteralExpr(info_result,v0.min(v1));
 85			if (op.equals("MAX"))
 86				return ExprFactory.makeIntLiteralExpr(info_result,v0.max(v1));
 87			if(op.equals("MINMAX"))
 88				return ExprFactory.makeTupleExpr(info_result.getSpan(), ExprFactory.makeIntLiteralExpr(NodeUtil.getSpan(arg0),v0.min(v1)),ExprFactory.makeIntLiteralExpr(NodeUtil.getSpan(arg1),v0.max(v1)));
 89			if(op.equals("CHOOSE"))
 90				return ExprFactory.makeIntLiteralExpr(info_result.getSpan(),choose(v0,v1));
 91			boolean lt = v0.compareTo(v1) == -1 ? true : false;
 92			boolean gt = v0.compareTo(v1) == 1 ? true : false; 
 93			boolean eq = v0.equals(v1);
 94			if (op.equals("<"))
 95				return ExprFactory.makeBooleanLiteralExpr(info_result,lt);
 96			if (op.equals("<="))
 97				return ExprFactory.makeBooleanLiteralExpr(info_result,lt || eq);
 98			if (op.equals(">"))
 99				return ExprFactory.makeBooleanLiteralExpr(info_result,gt);
100			if (op.equals(">="))
101				return ExprFactory.makeBooleanLiteralExpr(info_result,gt || eq);
102			if (op.equals("=")) 
103				return ExprFactory.makeBooleanLiteralExpr(info_result, eq);
104			if (op.equals("NE"))
105				return ExprFactory.makeBooleanLiteralExpr(info_result, lt || gt);
106			List<Expr> args = Arrays.asList(arg0,arg1);
107			return new OpExpr(info_result, op_result, args);
108			
109		}
110		
111		@Override
112	    public Node forChainExprOnly(ChainExpr that, ExprInfo info_result, Expr first_result, List<Link> links_result) {
113	
114			if (first_result instanceof IntLiteralExpr) {
115				if (links_result.size() == 0) throw new CompilerError("The list of links is empty");
116				Link arg = links_result.get(0);
117				if (arg.getExpr() instanceof IntLiteralExpr) {
118					Node folded = foldBinaryOperator(arg.getOp(),info_result,first_result,arg.getExpr());
119					if (links_result.size() == 1)	
120						return folded;
121					else {
122						if (folded instanceof BooleanLiteralExpr)	{
123							if (((BooleanLiteralExpr) folded).getBooleanVal() == 0) 
124								return ExprFactory.makeBooleanLiteralExpr(info_result,false);
125							else {
126								Expr e = links_result.remove(0).getExpr(); 
127							    return forChainExprOnly(that,info_result,e,links_result);
128							}
129						}
130						else 
131							throw new CompilerError("One of the link in a chained expression produced something other than a boolean literal during folding.");
132						
133					}
134				}	
135				
136			}
137			
138			if (that.getInfo() == info_result && that.getFirst() == first_result && that.getLinks() == links_result) return that;
139	        return new ChainExpr(info_result, first_result, links_result);
140	    }
141	    	
142		@Override
143		public Node forOpExprOnly(OpExpr that, ExprInfo info_result, FunctionalRef op_result, List<Expr> args_result) {
144			
145			if (args_result.size()==1) {    
146	
147				Expr arg = args_result.get(0);
148				if (arg instanceof IntLiteralExpr) {
149					
150					BigInteger v = ((IntLiteralExpr)args_result.get(0)).getIntVal();
151					String op = op_result.toString();
152					if (op.equals("prefix -") || op.equals("prefix BOXMINUS") || op.equals("prefix DOTMINUS")) 
153						return ExprFactory.makeIntLiteralExpr(info_result, v.negate());
154					if (op.equals("|_|")) 
155						return ExprFactory.makeIntLiteralExpr(info_result, v.abs());
156					if (op.equals("prefix NOT"))
157						return ExprFactory.makeIntLiteralExpr(info_result,v.not());
158					
159				}
160				
161			}	
162	
163			if (args_result.size() ==2) {
164				
165				Expr arg0 = args_result.get(0);
166				Expr arg1 = args_result.get(1);
167				if (arg0 instanceof IntLiteralExpr && arg1 instanceof IntLiteralExpr) 
168					return foldBinaryOperator(op_result,info_result,arg0,arg1);
169								
170			}
171	
172			if (that.getInfo() == info_result && that.getOp() == op_result && that.getArgs() == args_result) return that;
173			return new OpExpr(info_result, op_result, args_result);
174		}
175	
176	}
