+    /**
+     * The number type at which the coercion desugarer typed a numeral, or ""
+     * for a numeral of its own type.
+     */
+    private static String numeralTarget(Expr x) {
+        Option<Type> t = x.getInfo().getExprType();
+        if (t.isSome() && t.unwrap() instanceof TraitType) {
+            TraitType tt = (TraitType) t.unwrap();
+            if (tt.getArgs().isEmpty()) return tt.getName().getText();
+        }
+        return "";
+    }
+
+    /** The double nearest the rational n/d, d positive: one rounding, to nearest even. */
+    static double roundToDouble(BigInteger n, BigInteger d) {
+        if (n.signum() == 0) return 0.0;
+        BigInteger m = n.abs();
+        int shift = 56 - (m.bitLength() - d.bitLength());
+        BigInteger[] qr = (shift >= 0 ? m.shiftLeft(shift) : m).divideAndRemainder(shift >= 0 ? d : d.shiftLeft(-shift));
+        BigInteger q = qr[1].signum() == 0 ? qr[0] : qr[0].setBit(0);
+        double v = Math.scalb(q.doubleValue(), -shift);
+        return n.signum() < 0 ? -v : v;
+    }
+
+    /** The float nearest the rational n/d, d positive: one rounding, to nearest even. */
+    static float roundToFloat(BigInteger n, BigInteger d) {
+        if (n.signum() == 0) return 0.0f;
+        BigInteger m = n.abs();
+        int shift = 28 - (m.bitLength() - d.bitLength());
+        BigInteger[] qr = (shift >= 0 ? m.shiftLeft(shift) : m).divideAndRemainder(shift >= 0 ? d : d.shiftLeft(-shift));
+        BigInteger q = qr[1].signum() == 0 ? qr[0] : qr[0].setBit(0);
+        float v = Math.scalb(q.floatValue(), -shift);
+        return n.signum() < 0 ? -v : v;
+    }
