+        if (typed.equals("ZZ")) {
+            addLineNumberInfo(x);
+            mv.visitLdcInsn(bi.toString());
+            mv.visitMethodInsn(INVOKESTATIC, NamingCzar.internalFortressZZ, NamingCzar.make,
