+	/** A numeral's exact value, numerator and positive denominator in lowest terms; null for any other expression. */
+	public static BigInteger[] exactValue(Expr e) {
+		if (e instanceof IntLiteralExpr) return new BigInteger[] { ((IntLiteralExpr) e).getIntVal(), BigInteger.ONE };
+		if (e instanceof FloatLiteralExpr) {
+			FloatLiteralExpr f = (FloatLiteralExpr) e;
+			BigInteger den = BigInteger.valueOf(f.getDenomBase()).pow(f.getDenomPower());
+			return lowest(f.getIntPart().multiply(den).add(f.getNumerator()), den);
+		}
+		return null;
+	}
+
+	private static BigInteger[] lowest(BigInteger n, BigInteger d) {
+		if (d.signum() < 0) { n = n.negate(); d = d.negate(); }
+		BigInteger g = n.gcd(d);
+		if (g.signum() != 0 && !g.equals(BigInteger.ONE)) { n = n.divide(g); d = d.divide(g); }
+		return new BigInteger[] { n, d };
+	}
+
+	private static final BigInteger TWO = BigInteger.valueOf(2), FIVE = BigInteger.valueOf(5);
+
+	/**
+	 * The numeral of an exact value: an integer numeral, or, where an operand had
+	 * a radix point or the value is not an integer, a numeral with one, in
+	 * decimal where the denominator divides a power of ten.
+	 */
+	static Expr numeralOf(ExprInfo info, BigInteger n, BigInteger d, boolean point) {
+		if (!point && d.equals(BigInteger.ONE)) return ExprFactory.makeIntLiteralExpr(info, n);
+		int twos = 0, fives = 0;
+		BigInteger r = d;
+		while (r.mod(TWO).signum() == 0) { r = r.divide(TWO); twos++; }
+		while (r.mod(FIVE).signum() == 0) { r = r.divide(FIVE); fives++; }
+		if (r.equals(BigInteger.ONE)) {
+			int k = Math.max(Math.max(twos, fives), 1);
+			BigInteger scaled = n.multiply(BigInteger.TEN.pow(k)).divide(d);
+			String text = new java.math.BigDecimal(scaled, k).toPlainString();
+			return new FloatLiteralExpr(info, text, BigInteger.ZERO, scaled, 10, k);
+		}
+		if (d.bitLength() > 31) return null;
+		return new FloatLiteralExpr(info, n + "/" + d, BigInteger.ZERO, n, d.intValue(), 1);
+	}
+
+	/**
+	 * Numeral arithmetic folds exactly into one numeral, the Working Draft's
+	 * static expressions (constant.tex, "Static Expressions"; literals.tex): +, -,
+	 * multiplication, / by a nonzero numeral, and ^ by an integer numeral, where
+	 * an integer base takes no negative exponent. A result that IEEE arithmetic
+	 * could make a negative zero does not fold. Null where nothing folds.
+	 */
+	private static Expr foldExact(String op, ExprInfo info, Expr arg0, Expr arg1) {
+		BigInteger[] a = exactValue(arg0), b = exactValue(arg1);
+		if (a == null || b == null) return null;
+		boolean point = arg0 instanceof FloatLiteralExpr || arg1 instanceof FloatLiteralExpr;
+		BigInteger[] r;
+		if (op.equals("+")) r = lowest(a[0].multiply(b[1]).add(b[0].multiply(a[1])), a[1].multiply(b[1]));
+		else if (op.equals("-")) r = lowest(a[0].multiply(b[1]).subtract(b[0].multiply(a[1])), a[1].multiply(b[1]));
+		else if (op.equals("juxtaposition") || op.equals("DOT") || op.equals("TIMES") || op.equals("\u00B7") || op.equals("\u00D7")) {
+			if (point && (a[0].signum() == 0 || b[0].signum() == 0) && (a[0].signum() < 0 || b[0].signum() < 0)) return null;
+			r = lowest(a[0].multiply(b[0]), a[1].multiply(b[1]));
+		} else if (op.equals("/")) {
+			if (b[0].signum() == 0) return null;
+			if (a[0].signum() == 0 && b[0].signum() < 0) return null;
+			r = lowest(a[0].multiply(b[1]), a[1].multiply(b[0]));
+			point = true;
+		} else if (op.equals("^")) {
+			if (!(arg1 instanceof IntLiteralExpr)) return null;
+			BigInteger e = ((IntLiteralExpr) arg1).getIntVal();
+			if (e.abs().compareTo(BigInteger.valueOf(4096)) > 0) return null;
+			if ((long) e.abs().intValue() * Math.max(a[0].bitLength(), a[1].bitLength()) > 65536) return null;
+			int k = e.intValue();
+			if (k < 0) {
+				if (!(arg0 instanceof FloatLiteralExpr) || a[0].signum() == 0) return null;
+				r = lowest(a[1].pow(-k), a[0].pow(-k));
+			} else r = new BigInteger[] { a[0].pow(k), a[1].pow(k) };
+			point = arg0 instanceof FloatLiteralExpr;
+		} else return null;
+		return numeralOf(info, r[0], r[1], point);
+	}
+
 	private Node foldBinaryOperator(FunctionalRef op_result, ExprInfo info_result, Expr arg0, Expr arg1) {
