import java.lang.reflect.Method;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.Random;
public class RoundCheck {
  public static void main(String[] a) throws Exception {
    Class<?> c = Class.forName("com.sun.fortress.compiler.codegen.CodeGen");
    Method d = c.getDeclaredMethod("roundToDouble", BigInteger.class, BigInteger.class); d.setAccessible(true);
    Method f = c.getDeclaredMethod("roundToFloat", BigInteger.class, BigInteger.class); f.setAccessible(true);
    String[] fixed = {"1.2246467991473532", "0.9999999999999999", "0.77425264282026984", "0.1", "3.1415926535897932384", "1.00390625000000000001", "2.5", "1e-320"};
    for (String s : fixed) {
      BigDecimal b = new BigDecimal(s);
      BigInteger n = b.unscaledValue(), den = BigInteger.TEN.pow(Math.max(b.scale(),0));
      if (b.scale() < 0) { n = n.multiply(BigInteger.TEN.pow(-b.scale())); den = BigInteger.ONE; }
      System.out.println(s + " -> " + d.invoke(null, n, den) + " (Double.parseDouble " + Double.parseDouble(s) + ") float " + f.invoke(null, n, den) + " (Float.parseFloat " + Float.parseFloat(s) + ")");
    }
    Random r = new Random(29);
    int bad = 0, badf = 0, N = 200000;
    for (int i = 0; i < N; i++) {
      int digits = 1 + r.nextInt(25), scale = r.nextInt(40) - 5;
      BigInteger n = new BigInteger(digits * 4, r); if (r.nextBoolean()) n = n.negate();
      BigDecimal b = new BigDecimal(n, scale);
      BigInteger num = b.unscaledValue(), den = BigInteger.ONE;
      if (b.scale() > 0) den = BigInteger.TEN.pow(b.scale()); else num = num.multiply(BigInteger.TEN.pow(-b.scale()));
      double got = (Double) d.invoke(null, num, den), want = b.doubleValue();
      float gf = (Float) f.invoke(null, num, den), wf = b.floatValue();
      if (Double.doubleToRawLongBits(got) != Double.doubleToRawLongBits(want) && !(num.signum()==0)) bad++;
      if (Float.floatToRawIntBits(gf) != Float.floatToRawIntBits(wf) && !(num.signum()==0)) badf++;
    }
    System.out.println("random decimals: " + N + ", double mismatches " + bad + ", float mismatches " + badf);
  }
}
